import{_ as p,c as r,o,a4 as s}from"./chunks/framework.BU14wsQo.js";const n="/bug/trump-visit-huang-confirm.jpg",g="/bug/trump-visit-alaska-stop.jpg",a="/bug/trump-visit-huang-on-site.jpg",i="/bug/trump-visit-ceo-list.png",C=JSON.parse('{"title":"特朗普访华团再加一人：老黄，我 tm 来了！","description":"","frontmatter":{},"headers":[],"relativePath":"bug/trump-visit-ceo-list.md","filePath":"bug/trump-visit-ceo-list.md","lastUpdated":1778656220000}'),e={name:"bug/trump-visit-ceo-list.md"};function l(c,t,m,u,_,b){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="特朗普访华团再加一人-老黄-我-tm-来了" tabindex="-1">特朗普访华团再加一人：老黄，我 tm 来了！ <a class="header-anchor" href="#特朗普访华团再加一人-老黄-我-tm-来了" aria-label="Permalink to &quot;特朗普访华团再加一人：老黄，我 tm 来了！&quot;">​</a></h1><p>原本是 <strong>16 人访华天团</strong>。</p><p>结果临起飞前，名单又补进了一个最关键的人物：</p><p><strong>黄仁勋。</strong></p><p>这次不是小道消息，也不是市场猜测，而是媒体报道和现场照片都对上了。</p><p><img src="'+n+'" alt="黄仁勋确认加入访华团" loading="lazy"></p><p><strong>彭博社</strong> 的消息说得很直接：</p><p><strong>英伟达 CEO 黄仁勋，作为最后时刻新增成员，加入特朗普访华团。</strong></p><p>一句话，分量很重。</p><p>因为这不是普通企业家&quot;随团露面&quot;，而是 <strong>AI 芯片时代最核心的那个人，正式进场了。</strong></p><p><img src="'+g+'" alt="阿拉斯加经停现场" loading="lazy"></p><p><img src="'+a+'" alt="黄仁勋现场画面" loading="lazy"></p><p>更绝的是后面这两张现场图。</p><p>地点就在 <strong>阿拉斯加经停现场</strong>。<br> 一张拍到飞机经停画面，一张直接拍到黄仁勋本人站在停机坪上。</p><p>那个味道就一句话：</p><p><strong>老黄：我 tm 来了。</strong></p><hr><p>之前的名单已经够豪华了，现在黄仁勋补位，整个访华团直接从 <strong>16 人升级到 17 人</strong>。</p><p><img src="'+i+'" alt="17人访华团核心名单" loading="lazy"></p><p>我给大家极简过一遍，这 17 个人和他们背后的公司到底都是什么分量。</p><p><strong>1. 马斯克｜ Tesla / SpaceX</strong><br> 一个做电动车，一个做火箭和卫星互联网。马斯克代表的不是单一公司，而是美国最强的工业科技叙事。</p><p><strong>2. 库克｜ Apple</strong><br> 苹果 CEO。手里握着 iPhone、App Store 和全球消费电子供应链，中国市场对苹果的重要性不用多说。</p><p><strong>3. 拉里·芬克｜ BlackRock</strong><br> 贝莱德掌门人，全球最大资管公司之一。影响力不在产品，而在资本流向和全球资产配置。</p><p><strong>4. 史蒂芬·施瓦茨曼｜ Blackstone</strong><br> 黑石集团创始人，华尔街最有代表性的私募巨头之一，横跨地产、并购、基础设施和全球投资。</p><p><strong>5. 凯利·奥特伯格｜ Boeing</strong><br> 波音 CEO，代表美国航空制造业和大型工业出口能力。</p><p><strong>6. 布莱恩·赛克斯｜ Cargill</strong><br> 嘉吉负责人。农业、大宗商品、粮食贸易背后的超级巨头，和全球供应链联系极深。</p><p><strong>7. 简·弗雷泽｜ Citi</strong><br> 花旗 CEO，全球银行业核心人物之一，国际金融网络和跨境业务影响力很强。</p><p><strong>8. 吉姆·安德森｜ Coherent</strong><br> Coherent 主要做激光、光通信和高端器件，是先进制造和半导体链条里的关键玩家。</p><p><strong>9. 拉里·卡尔普｜ GE Aerospace</strong><br> GE 航空航天负责人，核心是航空发动机、航材和高端工业技术。</p><p><strong>10. 大卫·所罗门｜ Goldman Sachs</strong><br> 高盛 CEO。华尔街投行门面人物之一，代表的是金融市场、并购融资和国际资本话语权。</p><p><strong>11. 雅各布·泰森｜ Illumina</strong><br> 因美纳负责人，基因测序领域龙头公司，属于生命科学和医疗科技核心企业。</p><p><strong>12. 迈克尔·米巴赫｜ Mastercard</strong><br> 万事达卡 CEO，全球支付清算网络的关键一环。</p><p><strong>13. 迪娜·鲍威尔·麦考密克｜ Meta</strong><br> Meta 高层，连接科技平台、公共政策和国际事务，不只是企业代表，也有很强政策色彩。</p><p><strong>14. 桑杰·梅赫罗特拉｜ Micron</strong><br> 美光 CEO，全球存储芯片大厂，处在半导体产业链核心位置。</p><p><strong>15. 安蒙｜ Qualcomm</strong><br> 高通 CEO，手机芯片、通信专利、终端生态的代表人物。</p><p><strong>16. 瑞安·麦金纳尼｜ Visa</strong><br> Visa CEO，和万事达卡一起，基本代表了全球支付体系的另一半。</p><p><strong>17. 黄仁勋｜ NVIDIA</strong><br> 英伟达 CEO。AI 芯片、算力基础设施、训练集群，今天全球 AI 产业最绕不过去的公司之一。</p><hr><p>看到这里你就会发现：</p><p>这已经不是一次普通的企业家陪同访问。</p><p>这是 <strong>科技、金融、航空、农业、支付、芯片、AI</strong> 一整套美国顶级商业力量，集体到场。</p><p>而黄仁勋最后补位，让这次访华的象征意义一下子又上去了。</p><p>因为今天最关键的问题已经不是谁做手机、谁做汽车、谁做支付。</p><p>而是：</p><p><strong>谁握着 AI 时代最核心的算力入口。</strong></p><p>所以这次最值得看的，不只是&quot;谁来了&quot;。</p><p>而是：</p><p><strong>老黄来了以后，接下来会谈什么。</strong></p>',48)])])}const h=p(e,[["render",l]]);export{C as __pageData,h as default};
